alter table public.site_content_blocks add column if not exists page_path text not null default '/', add column if not exists subtitle text, add column if not exists secondary_cta_label text, add column if not exists secondary_cta_link text, add column if not exists background_image_url text, add column if not exists content_settings jsonb not null default '{}'::jsonb;
create table if not exists public.platform_feature_content (id uuid primary key default gen_random_uuid(),platform_key text not null,module_key text not null,feature_key text not null,title text not null,description text,icon_key text,badge_text text,help_text text,cta_label text,cta_link text,sort_order integer not null default 0,is_visible boolean not null default true,is_enabled boolean not null default true,settings jsonb not null default '{}'::jsonb,created_by uuid references auth.users(id),updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(platform_key,module_key,feature_key));
alter table public.platform_feature_content enable row level security;
create policy "platform feature content super admin manage" on public.platform_feature_content for all to authenticated using (private.is_admin(array['super_admin']::public.user_role[])) with check (private.is_admin(array['super_admin']::public.user_role[]));
create policy "platform feature content authenticated read" on public.platform_feature_content for select to authenticated using (is_visible and is_enabled);
create index if not exists platform_feature_content_platform_idx on public.platform_feature_content(platform_key,module_key,sort_order);